<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { cn } from '../../utils.js'; import AnsiText from './AnsiText.svelte'; import { useTerminalContext } from './context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { class?: string; children?: Snippet; maxHeight?: string; } let { class: className = '', children, maxHeight, ...rest }: Props = $props(); const terminal = useTerminalContext('TerminalContent'); let element = $state<HTMLDivElement>(); $effect(() => { if (terminal.autoScroll && element) element.scrollTop = element.scrollHeight; });</script>
<div {...rest} bind:this={element} class={cn('svadmin-ai-terminal-part__content', className)} style:--terminal-max-height={maxHeight} data-slot="terminal-content" role="log" aria-live="polite" aria-busy={terminal.isStreaming}>{#if children}{@render children()}{:else}<pre><AnsiText text={terminal.output} />{#if terminal.isStreaming}<span class="svadmin-ai-terminal-part__cursor" aria-hidden="true"></span>{/if}</pre>{/if}</div>
<style>.svadmin-ai-terminal-part__content { max-height: var(--terminal-max-height, 24rem); overflow: auto; padding: .8rem; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: .78rem; line-height: 1.55; }.svadmin-ai-terminal-part__content pre { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; }.svadmin-ai-terminal-part__cursor { display: inline-block; width: .45rem; height: 1em; margin-left: .25rem; vertical-align: -.15em; background: currentColor; animation: svadmin-ai-terminal-cursor 1s steps(2, jump-none) infinite; } @keyframes svadmin-ai-terminal-cursor { 50% { opacity: 0; } }</style>
